import pymysql

from silence.exceptions import HTTPError

###############################################################################
# Translates the errors of MariaDB into HTTP errors with a clear message.
# The same rules apply to every endpoint, autogenerated or custom.
###############################################################################

# Errors caused by the data that the client sent: 400 with the DB message
CLIENT_ERRORS = {
    1048: "A required value is missing",          # Column cannot be null
    1062: "Duplicate value",                      # UNIQUE / PRIMARY KEY
    1264: "Value out of range",
    1265: "Value too long or not valid",          # Data truncated
    1292: "Incorrect date or time value",
    1364: "A required value is missing",          # Field doesn't have a default value
    1366: "Incorrect value",
    1406: "Value too long",
    1451: "The row is referenced by other rows",  # FK on delete/update
    1452: "The referenced row does not exist",    # FK on insert/update
    3819: "A CHECK constraint failed",            # MySQL
    4025: "A CHECK constraint failed",            # MariaDB
}

# SIGNAL SQLSTATE '45000' in a trigger or procedure
SIGNAL_ERRORS = {1644}

# The database is not reachable or the credentials are wrong
CONNECTION_ERRORS = {1044, 1045, 1049, 2002, 2003, 2005, 2006, 2013}


def db_error_info(exc):
    '''Returns (errno, message) of a PyMySQL exception'''
    if isinstance(exc, pymysql.MySQLError) and len(exc.args) >= 2:
        return exc.args[0], str(exc.args[1])
    return None, str(exc)


def to_http_error(db_error, context=None):
    '''Converts a DatabaseError into an HTTPError'''
    exc = db_error.__cause__ or db_error
    errno, msg = db_error_info(exc)

    if errno in SIGNAL_ERRORS:
        # The message of the SIGNAL (e.g., "RN03: ...") reaches the client as is
        return HTTPError(400, msg, payload={"sqlError": errno})

    if errno in CLIENT_ERRORS:
        return HTTPError(400, f"{CLIENT_ERRORS[errno]}: {msg}", payload={"sqlError": errno})

    if errno in CONNECTION_ERRORS:
        return HTTPError(503, f"Cannot connect to the database: {msg}", payload={"sqlError": errno})

    # Anything else is a problem in the SQL of the endpoint, not in the request
    where = f" in {context}" if context else ""
    return HTTPError(500, f"SQL error{where}: {msg}", exc_class=type(exc).__name__,
                     payload={"sqlError": errno} if errno else None)
